$js = <<<'JS'
(()=>{function boot(){document.querySelectorAll('.zo-game-root--mint-delivery-rush').forEach(game=>{if(game.dataset.ready)return;game.dataset.ready='1';const all=JSON.parse(game.dataset.labels),t=all[game.dataset.lang]||all.tr;const $=s=>game.querySelector(s),status=$('.status'),scoreEl=$('.score');let score=0,ended=false;const say=s=>status.textContent=s;function points(n){score=n;scoreEl.textContent=n;}
const canvas=$('canvas'),ctx=canvas.getContext('2d');let lane=1,x=220,items=[],distance=0,lives=3,active=false,paused=false,last=0,spawnAt=0,invincible=0,raf=0;const pause=$('.pause'),life=$('.life');
function rounded(x,y,w,h,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function paint(){ctx.fillStyle='#193c46';ctx.fillRect(0,0,440,480);for(let i=0;i<8;i++){let yy=(i*85+distance*3)%560-70;rounded(12,yy,25,42,10,'#347564');rounded(403,yy+30,25,42,10,'#347564');}rounded(52,-20,336,530,10,'#283550');ctx.strokeStyle='#7b899c';ctx.lineWidth=4;ctx.setLineDash([25,22]);ctx.lineDashOffset=distance*3;[164,276].forEach(v=>{ctx.beginPath();ctx.moveTo(v,0);ctx.lineTo(v,480);ctx.stroke();});ctx.setLineDash([]);items.forEach(o=>{const xx=108+o.lane*112;if(o.coin){ctx.fillStyle='#ffe48c';ctx.beginPath();ctx.arc(xx,o.y,17,0,Math.PI*2);ctx.fill();ctx.fillStyle='#79541d';ctx.font='bold 20px system-ui';ctx.textAlign='center';ctx.fillText('★',xx,o.y+7);}else{rounded(xx-28,o.y-30,56,60,8,'#fb9878');rounded(xx-24,o.y-9,48,12,3,'#ffe2b2');}});ctx.globalAlpha=invincible>0?.55:1;rounded(x-26,373,52,76,13,'#68ead3');rounded(x-19,386,38,21,5,'#19475c');rounded(x-17,418,34,20,5,'#fcdb91');rounded(x-32,387,7,17,2,'#101e31');rounded(x+25,387,7,17,2,'#101e31');ctx.globalAlpha=1;ctx.fillStyle='#14243b';ctx.fillRect(60,12,320,7);ctx.fillStyle='#68ead3';ctx.fillRect(60,12,320*Math.min(distance/1000,1),7);if(!active||paused){ctx.fillStyle='#101a32bb';ctx.fillRect(0,0,440,480);ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='bold 22px system-ui';ctx.fillText(ended?(distance>=1000?'★ ★ ★':'↻'):(paused?t.pause:t.start),220,245);}}
function stop(win){ended=true;active=false;pause.disabled=true;say(win?t.win:t.over);paint();}
function step(time){if(!game.isConnected)return;const dt=Math.min((time-last)/1000,.04);last=time;if(active&&!paused){distance+=dt*35;invincible=Math.max(0,invincible-dt);x+=(108+lane*112-x)*Math.min(1,dt*18);const speed=170+Math.min(distance,1000)*.16;spawnAt-=dt;if(spawnAt<=0){const blocked=Math.floor(Math.random()*3);items.push({lane:blocked,y:-40,coin:false});items.push({lane:(blocked+1+Math.floor(Math.random()*2))%3,y:-40,coin:true});spawnAt=Math.max(.7,1.35-distance/1900);}items.forEach(o=>{o.y+=speed*dt;if(!o.hit&&Math.abs(o.y-411)<43&&Math.abs(108+o.lane*112-x)<42){o.hit=true;if(o.coin){points(score+25);}else if(invincible<=0){lives--;invincible=1.1;life.textContent='♥'.repeat(lives)+'♡'.repeat(3-lives);if(lives<=0)stop(false);}}});items=items.filter(o=>o.y<530&&!o.hit);$('.distance').textContent=Math.min(1000,Math.floor(distance))+' / 1000';if(active&&distance>=1000){points(score+100);stop(true);}}paint();if(active)raf=requestAnimationFrame(step);}
function reset(){cancelAnimationFrame(raf);lane=1;x=220;items=[];distance=0;lives=3;spawnAt=.7;invincible=0;active=true;paused=false;ended=false;points(0);life.textContent='♥♥♥';pause.disabled=false;pause.textContent=t.pause;last=performance.now();say(t.instructions);raf=requestAnimationFrame(step);canvas.focus({preventScroll:true});}
function steer(n){if(active&&!paused)lane=Math.max(0,Math.min(2,lane+n));}
$('.left').addEventListener('click',()=>steer(-1));$('.right').addEventListener('click',()=>steer(1));$('.start').addEventListener('click',reset);function toggle(){if(!active)return;paused=!paused;pause.textContent=paused?t.resume:t.pause;say(paused?t.pause:t.instructions);paint();}pause.addEventListener('click',toggle);game.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','a','d','A','D'].includes(e.key)){e.preventDefault();steer(['ArrowLeft','a','A'].includes(e.key)?-1:1);}if(e.code==='Space'&&e.target===canvas){e.preventDefault();toggle();}});canvas.addEventListener('pointerdown',e=>{if(!active)return;const r=canvas.getBoundingClientRect();steer(e.clientX-r.left<r.width/2?-1:1);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active&&!paused)toggle();});pause.disabled=true;say(t.ready);paint();
 });}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();})();
JS;
